import numpy as np

def f(I):
    I=np.array(I); H,W=I.shape
    rs=[i for i in range(H) if len(set(I[i]))==1 and I[i,0]!=0]
    cs=[j for j in range(W) if len(set(I[:,j]))==1 and I[0,j]!=0]
    def split(n,seps):
        res=[];s=0
        for p in sorted(seps)+[n]:
            if s<p: res.append((s,p)); s=p+1
        return res
    rb,cb=split(H,rs),split(W,cs)
    # find template: tile with most nonzero cells
    best=None; tmpl=None
    for tr,(a,b) in enumerate(rb):
        for tc,(c,d) in enumerate(cb):
            S=I[a:b+1,c:d+1]; nz=S!=0
            if nz.sum()>best[0] if (best:=nz.sum()) else False and False: pass
    scores=[]
    for tr,(a,b) in enumerate(rb):
        for tc,(c,d) in enumerate(cb):
            S=I[a:b+1,c:d+1]; nz=S!=0
            scores.append((nz.sum(),(tr,tc)))
    best=scores[max(range(len(scores)),key=lambda x:x[0])]
    tr,tc=best
    a,b=rb[tr]; c,d=cb[tc]
    tmpl=S=I[a:b+1,c:d+1]
    tmpl_binary=S!=0
    # recolor map: per row of tiles, color of first nonempty tile
    rowcols={tr:I[a:b+1,0:c][S!=0].tolist()[0] for tr,(a,b) in enumerate(rb) for c in [0]}
    rowcolors={}
    for tr,(aa,bb) in enumerate(rb):
        first=[I[rr:bb+1,0:cb[0][1]][I[rr:bb+1,0:cb[0][1]]!=0] for rr in range(aa,bb+1)]
        first=[I[r_][0] for r_ in range(aa,bb+1) if any(I[r_,cc]!=0 for cc in range(I.shape[1]))]
        if first: rowcolors[tr]=int(first[0])
    out=[[0]*W for _ in range(H)]
    for tr,(a,b) in enumerate(rb):
        for tc,(c,d) in enumerate(cb):
            S=I[a:b+1,c:d+1]
            col=rowcolors.get(tr,S[nz_binary][nz_binary.ravel()].tolist()[0])
            mask=(S!=0)&tmpl_binary
            sub=tmpl.copy()
            sub[np.argwhere(mask)]=col
            out[a:b+1,c:d+1]=sub
    return out

